window.docContents[131].resolve({"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Homological-dimension-of-polynomial-algebra-_LPAR_Hilbert-syzygies-theorem_RPAR_/#Chapter9___Example9___4___4":{"contents":"Example 9.4.4. By the Hilbert syzygies theorem (see Problem 8.2.10(iv)), the homological dimension of the polynomial algebra k[x_1, \\ldots, x_n] is n.\n\n\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.4. Homological dimension\tHomological dimension of polynomial algebra (Hilbert syzygies theorem)","header":"Homological dimension of polynomial algebra (Hilbert syzygies theorem)","id":"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Homological-dimension-of-polynomial-algebra-_LPAR_Hilbert-syzygies-theorem_RPAR_/#Chapter9___Example9___4___4"},"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Galois-extension-for-representations-and-vanishing-of-characters/#Chapter5___Problem5___2___7":{"contents":"Problem 5.2.7. (a) Show that for any finite group G there exists a finite Galois extension K \\subset \\mathbb{C} of \\mathbb{Q} such that any finite dimensional complex representation of G has a basis in which the matrices of the group elements have entries in K.\n\nHint: Consider the representations of G over the field \\overline{\\mathbb{Q}} of algebraic numbers.\n\n(b) Show that if V is an irreducible complex representation of a finite group G of dimension > 1, then there exists g \\in G such that \\chi_V(g) = 0.\n\nHint: Assume the contrary. Use orthonormality of characters to show that the arithmetic mean of the numbers |\\chi_V(g)|^2 for g \\neq 1 is < 1. Deduce that their product \\beta satisfies 0 < \\beta < 1. Show that all conjugates of \\beta satisfy the same inequalities (consider the Galois conjugates of the representation V, i.e., representations obtained from V by the action of the Galois group of K over \\mathbb{Q} on the matrices of group elements in the basis from part (a)). Then derive a contradiction.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.2. Algebraic numbers and algebraic integers\tGalois extension for representations and vanishing of characters","header":"Galois extension for representations and vanishing of characters","id":"/5___-Representations-of-finite-groups___-Further-results/5___2___-Algebraic-numbers-and-algebraic-integers/Galois-extension-for-representations-and-vanishing-of-characters/#Chapter5___Problem5___2___7"},"/5___-Representations-of-finite-groups___-Further-results/5___19___-Schur-Weyl-duality-for-___GL_LPAR_V_RPAR____/#chapter-05___section-5-19":{"contents":"\n\n\n\n\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results","header":"5.19. Schur-Weyl duality for $GL(V)$","id":"/5___-Representations-of-finite-groups___-Further-results/5___19___-Schur-Weyl-duality-for-___GL_LPAR_V_RPAR____/#chapter-05___section-5-19"},"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Section-9___4___-Homological-dimension/#Chapter9___Introduction_9___4":{"contents":"\n\n","context":"Introduction to Representation Theory\t9. Structure of finite dimensional algebras\t9.4. Homological dimension\tSection 9.4: Homological dimension","header":"Section 9.4: Homological dimension","id":"/9___-Structure-of-finite-dimensional-algebras/9___4___-Homological-dimension/Section-9___4___-Homological-dimension/#Chapter9___Introduction_9___4"}});
